/* Acesso centralizado à API; nenhuma credencial do MongoDB chega ao navegador. */
(function(){
  let remoteBookings=[];
  async function api(path, options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Não foi possível concluir a operação.');return data}
  async function loadBookings(){const data=await api('/api/bookings');remoteBookings=data.bookings||[];renderCalendar();renderReservations();if(current&&['admin','portaria'].includes(current.role))renderAdminReservations()}
  renderCalendar=()=>{const d=state.month,y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1).getDay(),last=new Date(y,m+1,0).getDate();monthLabel.textContent=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(d).replace(/^./,c=>c.toUpperCase());monthSelect.value=`${y}-${m}`;let h=Array(first).fill('<div class="day blank"></div>').join('');for(let n=1;n<=last;n++){const iso=`${y}-${String(m+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`,busy=remoteBookings.some(b=>b.room===state.room&&b.date===iso);h+=`<button class="day ${busy?'disabled':''} ${state.date===iso?'selected':''}" data-date="${iso}" ${busy?'disabled':''}>${n}<span class="status" style="background:${busy?'var(--red)':'var(--green)'}"></span></button>`}days.innerHTML=h;document.querySelectorAll('.day:not(.blank):not(.disabled)').forEach(b=>b.onclick=()=>{state.date=b.dataset.date;date.value=state.date;renderCalendar();updateSummary()})};
  renderReservations=()=>{const mine=current&&['admin','portaria'].includes(current.role)?remoteBookings:remoteBookings.filter(b=>b.user===current?.id);reservationList.innerHTML=mine.length?mine.map(b=>`<div class="reservation"><div><div class="res-date">${fmt(b.date)}</div><div class="res-detail">${b.room} · ${b.event} · ${b.start}–${b.end}</div></div><span class="pill">Solicitada</span></div>`).join(''):'<div class="empty">Você ainda não tem reservas.</div>'};
  renderAdminReservations=()=>{const el=document.querySelector('#adminReservations');if(!el)return;el.innerHTML=remoteBookings.length?remoteBookings.map(b=>`<div class="admin-reservation"><b>${b.room} · ${fmt(b.date)} · ${b.start}–${b.end}</b><small>Responsável: ${b.name} · Apartamento: ${b.apartment} · Telefone: ${b.phone} · ${b.event}</small></div>`).join(''):'<div class="empty">Nenhuma reserva registrada.</div>'};
  loginForm.onsubmit=async e=>{e.preventDefault();loginError.textContent='';try{const {user}=await api('/api/login',{method:'POST',body:JSON.stringify({identifier:loginId.value.trim(),password:loginPass.value})});current=user;openApp(user);await loadBookings();if(user.mustChange){securityBack.classList.remove('hidden');appView.classList.add('hidden')}}catch(err){loginError.textContent=err.message}};
  savePassword.onclick=async()=>{const p=newPassword.value,c=confirmPassword.value;if(p.length<8||p!==c){passwordError.textContent='Use pelo menos 8 caracteres e confirme a mesma senha.';return}try{await api('/api/password',{method:'PATCH',body:JSON.stringify({password:p})});current.mustChange=false;securityBack.classList.add('hidden');appView.classList.remove('hidden');show('Senha atualizada com sucesso.')}catch(err){passwordError.textContent=err.message}};
  accountForm.onsubmit=async e=>{e.preventDefault();try{const role=accountRole.value;await api('/api/accounts',{method:'POST',body:JSON.stringify({cpf:newCpf.value,name:newName.value,role})});accountForm.reset();await loadAccounts();show(role==='portaria'?'Conta superportaria criada.':'Conta de morador criada.')}catch(err){show(err.message)}};
  async function loadAccounts(){const data=await api('/api/accounts');const list=data.accounts||[];accountCount.textContent=list.length;accountList.innerHTML=list.length?list.map(a=>`<div class="account"><div><b>${a.name}</b><small>${a.role==='resident'?'CPF: '+a.id:'Usuário: '+a.id}</small></div><span class="badge">${a.role==='admin'?'Administrador':a.role==='portaria'?'Super Portaria':'Morador'}</span></div>`).join(''):'<div class="empty">Nenhuma conta cadastrada.</div>';renderAdminReservations()}
  const oldOpenApp=openApp;openApp=user=>{oldOpenApp(user);navAdmin.classList.toggle('hidden',user.role==='resident');if(user.role==='portaria'){navAdmin.textContent='';navAdmin.innerHTML='<span class="dot" style="background:#e4be7c"></span>Reservas da portaria'}};
  bookingForm.onsubmit=e=>{e.preventDefault();if(!state.date){show('Escolha uma data no calendário.');return}if(!name.value.trim()||!apartment.value.trim()||!phone.value.trim()){show('Preencha nome, apartamento e telefone.');return}termsModal.classList.remove('hidden')};
  signTerms.onclick=async()=>{if(!acceptTerms.checked){show('Marque a concordância com o termo para continuar.');return}try{await api('/api/bookings',{method:'POST',body:JSON.stringify({room:state.room,date:state.date,start:start.value,end:end.value,event:event.value,name:name.value,apartment:apartment.value,phone:phone.value})});termsModal.classList.add('hidden');bookingForm.reset();state.date='';await loadBookings();updateSummary();show('Termo assinado e reserva solicitada.')}catch(err){show(err.message)}};
  logout.onclick=async()=>{await api('/api/login',{method:'DELETE'}).catch(()=>{});location.reload()};
  navAdmin.addEventListener('click',()=>{if(current&&['admin','portaria'].includes(current.role)){loadBookings().then(()=>current.role==='admin'&&loadAccounts()).catch(err=>show(err.message))}});
})();
